  m=np.abs(old[:,1]-y)<.5;top=m&(old[:,2]>=np.percentile(old[m,2],90));slices.append({'yMm':y,'meanUpperSurfaceDisplacementMm':float((old[top,2]-new[top,2]).mean()),'roofBeforeMm':float(old[m,2].max()),'roofAfterMm':float(new[m,2].max())})
